def action_with_fallback(
    self,
    role: str,
    system: str,
    user: str,
) -> tuple[str, dict[str, Any]]:
    order = [role]
    for fallback in ("main", "large", "remote"):
        if fallback not in order and self._enabled(fallback):
            order.append(fallback)

    self.last_model_failures = 0
    errors: list[str] = []
    for candidate in order:
        try:
            backend = self.backend(candidate)
            raw = interruptible_call(
                lambda: backend.complete(system, user)
            )
            action = extract_action(raw)
            tool = str(action.get("tool", ""))
            args = action.get("args", {})
            if tool not in TOOLS or not isinstance(args, dict):
                raise HelixError(f"Invalid action from model: {action}")
            return candidate, action
        except Exception as exc:
            self.last_model_failures += 1
            errors.append(f"{candidate}: {exc}")
            print(f"[MODEL] {candidate} unusable: {exc}")

    raise HelixError("No model produced a valid action: " + " | ".join(errors))

def extract_action(text: str) -> dict[str, Any]:
    text = text.strip()
    try:
        value = json.loads(text)
        if isinstance(value, dict):
            return value
    except json.JSONDecodeError:
        pass

    match = re.search(r"\{.*\}", text, flags=re.DOTALL)
    if not match:
        raise HelixError(f"Model did not return JSON: {text[:500]}")
    try:
        value = json.loads(match.group(0))
    except json.JSONDecodeError as exc:
        raise HelixError(f"Invalid model JSON: {exc}: {text[:500]}") from exc
    if not isinstance(value, dict):
        raise HelixError("Model action must be a JSON object.")
    return value

